package no.stormberry.twinlit

import no.stormberry.twinlit.widget.TestFiles
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The app icon is option b1 "Sunset, moon above" (Marcos, 2026-11-22, DECISIONS D114), generated by
 * android/tools/build-launcher-icon.py from the three SVG layers in android/tools/launcher-icon/.
 * Source and file checks: every form of the icon in the app carries the source's own shapes and
 * colours, so a hand edit of a generated file, or a source change without a rerun, fails here.
 */
class LauncherIconTest {

    private val src = "android/tools/launcher-icon"
    private val drawables = "${TestFiles.RES}/drawable"

    private fun source(name: String) = TestFiles.requireAtRoot("$src/$name").readText()
    private fun res(path: String) = TestFiles.requireAtRoot("${TestFiles.RES}/$path").readText()

    private fun pathData(text: String, attr: String): List<String> =
        Regex("""(?<![\w:])$attr="([^"]+)"""").findAll(text).map { it.groupValues[1] }.toList()

    private fun colours(text: String, regex: Regex) = regex.findAll(text).map { it.groupValues[1].uppercase() }.toSet()

    @Test
    fun `the adaptive icon has a background, a foreground and a monochrome layer of its own`() {
        for (f in listOf("ic_launcher.xml", "ic_launcher_round.xml")) {
            val x = res("mipmap-anydpi-v26/$f")
            assertTrue(x.contains("""<background android:drawable="@drawable/ic_launcher_background" />"""))
            assertTrue(x.contains("""<foreground android:drawable="@drawable/ic_launcher_foreground" />"""))
            assertTrue(x.contains("""<monochrome android:drawable="@drawable/ic_launcher_monochrome" />"""))
        }
    }

    @Test
    fun `each layer carries the shapes of its source SVG`() {
        for ((svg, xml) in listOf(
            "background.svg" to "ic_launcher_background.xml",
            "foreground.svg" to "ic_launcher_foreground.xml",
            "monochrome.svg" to "ic_launcher_monochrome.xml",
        )) {
            val shapes = pathData(source(svg), "d")
            val drawn = pathData(res("drawable/$xml"), "android:pathData")
            assertTrue("$svg has shapes", shapes.isNotEmpty())
            assertEquals("$xml has the shapes of $svg, in order", shapes, drawn)
        }
    }

    @Test
    fun `the colours are the designed ones, the sky and the sun keep their gradients`() {
        val bg = res("drawable/ic_launcher_background.xml")
        assertTrue(bg.contains("""android:type="linear""""))
        for (c in listOf("#FF080C18", "#FF0D142E", "#FF3A2410", "#FF2A1A0C")) assertTrue(c, bg.contains(c))
        val fg = res("drawable/ic_launcher_foreground.xml")
        assertTrue(fg.contains("""android:type="radial""""))
        for (c in listOf("#FFFFF7A1", "#FFFFD700", "#FFFFB347", "#FFC8D8F0")) assertTrue(c, fg.contains(c))
    }

    @Test
    fun `the monochrome layer is one colour, so the system can tint it`() {
        val mono = res("drawable/ic_launcher_monochrome.xml")
        val used = colours(mono, Regex("""(?:fillColor|strokeColor)="(#[0-9A-Fa-f]{8})""""))
        assertEquals(setOf("#FFFFFFFF"), used)
        assertFalse(mono.contains("<gradient"))
    }

    @Test
    fun `the carousel card shows the whole tile from the same source`() {
        val card = res("drawable/labs_switcher_twinlit.xml")
        assertTrue(card.contains("""android:width="32dp""""))
        assertTrue(card.contains("<clip-path"))
        val drawn = pathData(card, "android:pathData")
        for (d in pathData(source("background.svg"), "d") + pathData(source("foreground.svg"), "d")) {
            assertTrue("a shape of the source is on the card", d in drawn)
        }
    }

    @Test
    fun `the store icon is 512 by 512 and the feature graphic 1024 by 500`() {
        fun size(path: String): Pair<Int, Int> {
            val b = TestFiles.requireAtRoot(path).readBytes()
            fun int(o: Int) = ((b[o].toInt() and 0xFF) shl 24) or ((b[o + 1].toInt() and 0xFF) shl 16) or
                ((b[o + 2].toInt() and 0xFF) shl 8) or (b[o + 3].toInt() and 0xFF)
            return int(16) to int(20)
        }
        assertEquals(512 to 512, size("fastlane/metadata/android/en-US/images/icon.png"))
        assertEquals(1024 to 500, size("fastlane/metadata/android/en-US/images/featureGraphic.png"))
    }

    @Test
    fun `the store icon is a 32-bit PNG that Play accepts, opaque`() {
        val b = TestFiles.requireAtRoot("fastlane/metadata/android/en-US/images/icon.png").readBytes()
        // IHDR: bit depth at byte 24, colour type at byte 25 (6 = RGBA, so 8 x 4 = 32 bits a pixel).
        assertEquals("bit depth", 8, b[24].toInt())
        assertEquals("colour type RGBA", 6, b[25].toInt())
    }

    @Test
    fun `no icon file or note is marked as a draft any more`() {
        for (f in listOf("$src/notes.md", "android/tools/build-launcher-icon.py")) {
            assertFalse("$f still says DRAFT", TestFiles.requireAtRoot(f).readText().contains("DRAFT"))
        }
        for (x in listOf("ic_launcher_background", "ic_launcher_foreground", "ic_launcher_monochrome", "labs_switcher_twinlit")) {
            assertFalse("$x still says DRAFT", TestFiles.requireAtRoot("$drawables/$x.xml").readText().contains("DRAFT"))
        }
    }

    @Test
    fun `the old night colour resource is gone, the icon background is the vector`() {
        assertFalse(res("values/colors.xml").contains("twinlit_icon_background"))
    }

    /**
     * The store icon and the ten legacy PNGs (API 24 and 25: the square and the round launcher icon in five
     * densities) are the b1 files and no other (R12, D128). `android/tools/launcher-icon/legacy-icons.sha256`
     * holds the SHA-256 of each, as `build-launcher-icon.py` wrote them (the store icon's pixels equal b1's
     * `icon-512.png`, checked when D120 was made); the old icon's PNGs, or any hand edit, fail here. After a
     * change of the SVG layers, run the generator and write the file again with `sha256sum`.
     */
    @Test
    fun `the store icon and the ten legacy launcher PNGs are the b1 files`() {
        val pins = TestFiles.requireAtRoot("$src/legacy-icons.sha256").readLines().filter { it.isNotBlank() }.map {
            val (hash, path) = it.split(Regex("""\s+"""), limit = 2)
            path to hash
        }
        val expected = listOf("fastlane/metadata/android/en-US/images/icon.png") +
            listOf("mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi").flatMap { d ->
                listOf("ic_launcher", "ic_launcher_round").map { "${TestFiles.RES}/mipmap-$d/$it.png" }
            }
        assertEquals("the pinned files", expected.sorted(), pins.map { it.first }.sorted())
        for ((path, hash) in pins) {
            val digest = java.security.MessageDigest.getInstance("SHA-256").digest(TestFiles.requireAtRoot(path).readBytes())
            assertEquals("$path is not the b1 file", hash, digest.joinToString("") { "%02x".format(it) })
        }
    }
}
